/*
 * Discourse 的 `select-kit`，尺寸只满足编辑器所需：一个
 * 页眉，打开后在紧下方（空间不足时在上方）显示带 "搜索…" 字段
 * 和列表的主体。方向键上下移动，Enter 选择，Esc 关闭；
 * 点击外部也关闭。
 *
 * 使用方传入已过滤的行（`rows(filter)`）、页眉内容
 * 以及选择时要做的事 —— 组件只负责打开、
 * 定位和导航。
 */
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import { t } from '../utils/settings';
const BODY_MIN_SPACE = 300;
export default class SelectKit extends Component {
  open = false;
  filter = '';
  highlighted = 0;
  above = false;
  outside = null;
  view() {
    const {
      className,
      header,
      caret = 'fas fa-angle-down',
      caretOpen = 'fas fa-angle-up',
      disabled,
      label
    } = this.attrs;
    return m("div", {
      className: classList('LcoySelectKit', className, {
        'is-expanded': this.open,
        'is-above': this.above,
        'is-disabled': disabled
      })
    }, m("button", {
      type: "button",
      className: "LcoySelectKit-header",
      disabled: disabled,
      "aria-haspopup": "listbox",
      "aria-expanded": this.open ? 'true' : 'false',
      "aria-label": label,
      onclick: () => this.open ? this.close() : this.show(),
      onkeydown: e => {
        if (!this.open && (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ')) {
          e.preventDefault();
          this.show();
        }
      }
    }, m("span", {
      className: "LcoySelectKit-headerContent"
    }, header), m(Icon, {
      name: this.open ? caretOpen : caret,
      className: "LcoySelectKit-caret"
    })), this.open && this.bodyView());
  }
  bodyView() {
    const rows = this.attrs.rows(this.filter);
    if (this.highlighted >= rows.length) this.highlighted = rows.length - 1;
    const filter = m("div", {
      className: "LcoySelectKit-filter"
    }, m("input", {
      type: "search",
      className: "LcoySelectKit-filterInput",
      placeholder: this.attrs.placeholder || t('composer.shell.search_placeholder'),
      value: this.filter,
      autocomplete: "off",
      spellcheck: false,
      oninput: e => {
        this.filter = e.target.value;
        this.highlighted = 0;
      },
      onkeydown: e => this.onkeydown(e, rows),
      oncreate: vnode => vnode.dom.focus()
    }), this.attrs.filterIcon && m(Icon, {
      name: "fas fa-magnifying-glass",
      className: "LcoySelectKit-filterIcon"
    }));
    const list = m("ul", {
      className: "LcoySelectKit-collection",
      role: "listbox",
      "aria-label": this.attrs.label
    }, rows.length ? rows.map((row, i) => m("li", {
      key: row.key,
      className: classList('LcoySelectKit-row', {
        'is-highlighted': i === this.highlighted,
        'is-selected': row.selected
      }),
      role: "option",
      "aria-selected": row.selected ? 'true' : 'false',
      title: row.title,
      onmouseenter: () => this.highlighted = i
      // 用 `mousedown` 而不是 `click`：在字段失去焦点之前完成选择。
      ,
      onmousedown: e => {
        e.preventDefault();
        this.choose(row.key);
      }
    }, row.content)) : m("li", {
      key: "empty",
      className: "LcoySelectKit-empty"
    }, this.attrs.emptyText || t('composer.shell.no_results')));
    const after = typeof this.attrs.after === 'function' ? this.attrs.after(this.filter) : this.attrs.after;

    // 向上打开时，搜索框位于下方、靠近页眉（与 Discourse 相同）。
    return m("div", {
      className: "LcoySelectKit-body",
      onmousedown: e => e.stopPropagation()
    }, this.above ? [after, list, this.attrs.before, filter] : [filter, this.attrs.before, list, after]);
  }
  onkeydown(e, rows) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      this.highlighted = Math.min(rows.length - 1, this.highlighted + 1);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      this.highlighted = Math.max(0, this.highlighted - 1);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const row = rows[this.highlighted];
      if (row) this.choose(row.key);
    } else if (e.key === 'Escape') {
      // 不让 Esc 传到编辑器（否则会关闭整个编辑器）。
      e.preventDefault();
      e.stopPropagation();
      this.close();
      this.element.querySelector('.LcoySelectKit-header')?.focus();
    } else if (e.key === 'Tab') {
      this.close();
    }
    this.scrollHighlightedIntoView();
  }
  scrollHighlightedIntoView() {
    requestAnimationFrame(() => {
      this.element?.querySelector('.LcoySelectKit-row.is-highlighted')?.scrollIntoView({
        block: 'nearest'
      });
    });
  }
  choose(key) {
    this.attrs.onselect(key);
    this.filter = '';
    if (!this.attrs.stayOpen) this.close();
    m.redraw();
  }
  show() {
    if (this.attrs.disabled) return;

    // 下方空间不足而上方充足时向上打开。
    const rect = this.element.getBoundingClientRect();
    const below = window.innerHeight - rect.bottom;
    this.above = below < BODY_MIN_SPACE && rect.top > below;
    this.open = true;
    this.filter = '';
    this.highlighted = this.attrs.highlightSelected ? this.attrs.rows('').findIndex(row => row.selected) : 0;
    this.outside = e => {
      if (!this.element.contains(e.target)) {
        this.close();
        m.redraw();
      }
    };
    document.addEventListener('mousedown', this.outside);
  }
  close() {
    this.open = false;
    if (this.outside) document.removeEventListener('mousedown', this.outside);
    this.outside = null;
  }
  onremove(vnode) {
    super.onremove(vnode);
    this.close();
  }
}
flarum.reg.add('lcoy-roselle', 'forum/composer/SelectKit', SelectKit);