/*
 * 最后一篇帖子之后的内容：主题按钮和建议主题。仅在 stream 到达末尾时出现
 * ——在长主题中间，后面的帖子还没加载，页脚会卡在中间。
 */
import Component from 'flarum/common/Component';
import SuggestedTopics from './SuggestedTopics';
import TopicFooter from './TopicFooter';
import TopicMap, { hasBottomTopicMap } from './TopicMap';
import { topicSettings } from '../ui';
export default class TopicEnd extends Component {
  view() {
    const {
      discussion,
      stream,
      page
    } = this.attrs;
    if (!stream || !stream.viewingEnd()) return null;
    const footer = topicSettings.footer();
    const suggested = topicSettings.suggested();
    if (!footer && !suggested) return null;
    return m("div", {
      className: "LcoyTopicEnd"
    }, topicSettings.map() && hasBottomTopicMap(discussion) && m(TopicMap, {
      discussion: discussion,
      position: "bottom"
    }), footer && m(TopicFooter, {
      discussion: discussion,
      page: page
    }), suggested && [m(SuggestedTopics, {
      key: discussion.id(),
      discussion: discussion
    })]);
  }
}
flarum.reg.add('lcoy-roselle', 'forum/topic/components/TopicEnd', TopicEnd);