/*
 * Discourse 的批量选择（面向有管理权限者）：列表栏中的按钮为每个
 * 主题启用复选框，并在列表上方显示操作栏——标记为已读、置顶、
 * 锁定、更改标签、隐藏、删除。
 *
 * 全部通过核心的 ItemLists 实现：按钮位于 `IndexPage.actionItems`
 * （主题的导航栏绘制在右侧），工具栏位于 `contentItems`，复选框位于
 * `DiscussionListItem.contentItems`。
 */
import { extend } from 'flarum/common/extend';
import IndexPage from 'flarum/forum/components/IndexPage';
import DiscussionListItem from 'flarum/forum/components/DiscussionListItem';
import Button from 'flarum/common/components/Button';
import Tooltip from 'flarum/common/components/Tooltip';
import classList from 'flarum/common/utils/classList';
import { t } from '../../../utils/settings';
import { bulkActions } from './actions';
import { bulkAvailable, loadedDiscussions, selection } from './selection';

/** MinimalDiscussionListItem（弹窗结果）继承自列表项；在那里没有选择功能。 */
function isMinimal(item) {
  return String(item.elementAttrs().className || '').includes('MinimalDiscussionListItem');
}
function toggleButton() {
  const label = selection.active ? t('extras.bulk.toggle_off') : t('extras.bulk.toggle_on');
  return m(Tooltip, {
    text: label
  }, m(Button, {
    className: classList('Button Button--icon LcoyBulk-toggle', {
      active: selection.active
    }),
    icon: "fas fa-list-check",
    "aria-label": label,
    "aria-pressed": selection.active ? 'true' : 'false',
    onclick: () => selection.setActive(!selection.active)
  }));
}
function bar() {
  const selected = selection.selected();
  const count = selected.length;
  const total = loadedDiscussions().length;
  const actions = bulkActions().filter(action => selected.some(discussion => action.applies(discussion)));
  return m("div", {
    className: "LcoyBulkBar",
    role: "toolbar",
    "aria-label": t('extras.bulk.bar_label')
  }, m("div", {
    className: "LcoyBulkBar-status"
  }, m("span", {
    className: "LcoyBulkBar-count"
  }, t('extras.bulk.selected', {
    count
  })), count < total ? m(Button, {
    className: "Button Button--link LcoyBulkBar-link",
    onclick: () => selection.selectAll()
  }, t('extras.bulk.select_all', {
    count: total
  })) : null, count > 0 && m(Button, {
    className: "Button Button--link LcoyBulkBar-link",
    onclick: () => selection.clear()
  }, t('extras.bulk.clear'))), m("div", {
    className: "LcoyBulkBar-actions"
  }, count === 0 && m("span", {
    className: "LcoyBulkBar-hint"
  }, t('extras.bulk.hint')), actions.map(action => m(Button, {
    className: classList('Button LcoyBulkBar-action', {
      'LcoyBulkBar-action--danger': action.danger
    }),
    icon: action.icon,
    onclick: () => action.run(selection.selected())
  }, action.label)), m(Button, {
    className: "Button Button--icon Button--link LcoyBulkBar-close",
    icon: "fas fa-times",
    "aria-label": t('extras.bulk.toggle_off'),
    onclick: () => selection.setActive(false)
  })));
}
export default function installBulkSelect() {
  extend(IndexPage.prototype, 'oninit', function () {
    // 另一个列表，另一份选择：在某个标签中勾选主题后切换标签，
    // 不能让操作仍然作用于已从屏幕上消失的内容。
    selection.setActive(false);
  });
  extend(IndexPage.prototype, 'actionItems', function (items) {
    if (!bulkAvailable()) return;
    items.add('lcoyBulk', toggleButton(), 5);
  });
  extend(IndexPage.prototype, 'contentItems', function (items) {
    if (!selection.active || !bulkAvailable()) return;

    // 位于导航栏（100）与列表（90）之间。
    items.add('lcoyBulkBar', bar(), 95);
  });
  extend(DiscussionListItem.prototype, 'oninit', function () {
    // 仅当 SubtreeRetainer 检测到变化时该项才会重绘；选择状态
    // 必须纳入该判断，否则复选框不会响应点击。
    this.subtree.check(() => selection.active, () => selection.active && selection.has(this.attrs.discussion));
  });
  extend(DiscussionListItem.prototype, 'contentItems', function (items) {
    if (!selection.active || isMinimal(this)) return;
    const discussion = this.attrs.discussion;
    const checked = selection.has(discussion);
    items.add('lcoyBulkCheck', m("label", {
      className: "LcoyBulkCheck",
      onclick: event => event.stopPropagation()
    }, m("input", {
      type: "checkbox",
      checked: checked,
      "aria-label": t('extras.bulk.select_one', {
        title: discussion.title()
      }),
      onclick: event => {
        selection.toggle(discussion, event.shiftKey);

        // shift+点击时最终状态来自区间而非本次点击：
        // 在此校正被点击的复选框，因为若其自身状态未变，
        // 该项甚至可能不会重绘（SubtreeRetainer）。
        event.currentTarget.checked = selection.has(discussion);
      }
    })),
    // 排在最前，包括手机端的头像（100）之前。
    110);
  });
  extend(DiscussionListItem.prototype, 'elementAttrs', function (attrs) {
    if (selection.active && selection.has(this.attrs.discussion)) {
      attrs.className = classList(attrs.className, 'LcoyBulk-selected');
    }
  });
}
flarum.reg.add('lcoy-roselle', 'forum/features/extras/bulk', installBulkSelect);